import os,json,subprocess,hashlib
from pathlib import Path
roots=('/etc/systemd/system','/etc/nginx','/etc/cron.d','/usr/local/bin','/usr/local/sbin','/srv/projects/fadego','/srv/projects/pink-iptv')
need={'fadego':'/etc/fadego-staging/','pink-iptv':'/etc/pink-iptv/','helper':'/usr/local/sbin/fadego-password'}
ignore={'.git','node_modules','.venv','vendor','private','data','backups','__pycache__','cache','dist','build','.next','sessions','releases','archive','artifacts','.runtime','output'}
out={'references':{},'scanned_regular_files':0,'skipped_large':0,'scan_complete':True,'units':{},'directory_listing':{},'helper':{}}
for base in roots:
 p=Path(base);found=[];dirs_count=0
 if not p.is_dir():continue
 for current,dirs,files in os.walk(p,followlinks=False):
  dirs_count+=1
  if dirs_count>25000:out['scan_complete']=False;break
  level=len(Path(current).relative_to(p).parts)
  if level>10:dirs[:]=[];continue
  dirs[:]=[d for d in dirs if d not in ignore]
  for fn in files:
   f=Path(current)/fn
   if f.is_symlink() or f.name.endswith(('.env','.pem','.key','.crt','.sqlite','.db','.dump','.gz','.zip','.jar','.log')):continue
   if f.suffix not in ('.py','.sh','.ts','.js','.tsx','.mjs','.cjs','.service','.timer','.conf','.json','.yml','.yaml','.md','.txt','') and f.name not in ('fadego-password',):continue
   try:
    if not f.is_file() or f.stat().st_size>500000:out['skipped_large']+=1;continue
    content=f.read_text(errors='replace')
    out['scanned_regular_files']+=1
    hits=[k for k,v in need.items() if v in content]
    if hits:found.append({'file':str(f),'references':hits})
    if out['scanned_regular_files']>40000:out['scan_complete']=False;break
   except Exception:pass
  if not out['scan_complete']:break
 out['references'][base]=found[:100]
for svc in ('fadego-staging','fadego-booking-email','pink-iptv-backend','pink-vpn'):
 p=subprocess.run(['systemctl','cat',svc],capture_output=True,text=True,timeout=12)
 s=p.stdout
 out['units'][svc]={'exists':p.returncode==0,'environment_paths':[x.strip() for x in s.splitlines() if x.strip().startswith('EnvironmentFile=')][:10],'fragment_paths':[x[:180] for x in s.splitlines() if x.startswith('# /etc/systemd/system/')],'active':subprocess.run(['systemctl','is-active',svc],capture_output=True,text=True,timeout=8).stdout.strip()}
for d in ('/etc/fadego-staging','/etc/pink-iptv'):
 p=Path(d)
 out['directory_listing'][d]=[x.name for x in p.iterdir()] if p.is_dir() else []
hp=Path('/usr/local/sbin/fadego-password')
if hp.is_file() and not hp.is_symlink():
 s=hp.read_bytes()
 out['helper']={'exists':True,'mode':oct(hp.stat().st_mode&0o777),'sha256':hashlib.sha256(s).hexdigest(),'references_fadego_etc':s.count(b'/etc/fadego-staging/'),'has_relative_run_dirs':b'BASH_SOURCE' in s or b'dirname \"$0\"' in s,'script_shebang':s.split(b'\n',1)[0].decode('utf-8','replace')[:100],'valid_bash':subprocess.run(['/bin/bash','-n',str(hp)],capture_output=True,timeout=10).returncode==0}
print(json.dumps(out,separators=(',',':')))
